gr_(){return"\u041f\u044f\u0442\u044c \u0441\u0442\u0430\u043d\u0446\u0438\u0439 \u043f\u043e \u043c\u0438\u043d\u0443\u0442\u0435, \u043f\u043e\u0442\u043e\u043c \u043c\u0438\u043d\u0443\u0442\u0430 \u043e\u0442\u0434\u044b\u0445\u0430. \u041f\u043e\u0441\u043b\u0435\u0434\u043d\u044e\u044e \u043c\u0438\u043d\u0443\u0442\u0443 \u043e\u0442\u0434\u044b\u0445\u0430 \u043c\u043e\u0436\u043d\u043e \u043d\u0435 \u0434\u043e\u0441\u0438\u0436\u0438\u0432\u0430\u0442\u044c."},
