gqm(){return"\u0422\u0440\u0438\u0434\u0446\u0430\u0442\u044c \u0440\u044b\u0432\u043a\u043e\u0432 \u043d\u0430 \u0432\u0440\u0435\u043c\u044f. \u0412 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u0430\u0445 \u0438\u0437 \u043e\u0434\u043d\u043e\u0433\u043e \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u044f \u043d\u0435 \u0441\u043f\u0440\u044f\u0447\u0435\u0448\u044c\u0441\u044f \u0437\u0430 \u0440\u0430\u0441\u043a\u043b\u0430\u0434\u043a\u043e\u0439."},
gqn(){return"\u0413\u0440\u0435\u0431\u043b\u044f, \u0442\u0440\u0430\u0441\u0442\u0435\u0440\u044b, \u043f\u043e\u0434\u0442\u044f\u0433\u0438\u0432\u0430\u043d\u0438\u044f \u2014 \u0442\u0440\u0438 \u0441\u0442\u0430\u043d\u0446\u0438\u0438 \u0431\u0435\u0437 \u043e\u0442\u0434\u044b\u0445\u0430. \u0412\u0435\u0441 \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u043d\u043e \u043b\u0451\u0433\u043a\u0438\u0439: \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u044e\u0442 \u043d\u0435 \u0441\u0438\u043b\u0443, \u0430 \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u044c \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0438\u0442\u044c \u043f\u043e\u0441\u043b\u0435 \u0433\u0440\u0435\u0431\u043b\u0438."},
